def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    result = []
    for cls in classes:
        if all(issubclass(cls, rcls) for rcls in result):
            continue
        result.append(cls)

    for j in range(len(result)):
        for i in range(j + 1, len(result)):
            if issubclass(result[j], result[i]):
                result[i] = result[j]

    return list(OrderedDict.fromkeys(result))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    seen = set()
    result = []

    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            bases = cls.__bases__
            for base in bases:
                if base not in seen:
                    result.append(base)
                    seen.add(base)
            result.append(cls)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    while True:
        changed = False
        for i in range(len(classes)):
            for j in range(i + 1, len(classes)):
                if issubclass(classes[j], classes[i]):
                    classes.pop(j)
                    changed = True
                elif classes[i] in classes[j].__bases__:
                    classes.pop(i)
