    merged_dict = {}
    for key_node, value_node in nodes:
        if key_node.value not in merged_dict:
            merged_dict[key_node.value] = value_node
        elif isinstance(value_node, ruamel.yaml.nodes.MappingNode):
            current_value_node = merged_dict[key_node.value]
            if isinstance(current_value_node, ruamel.yaml.nodes.MappingNode):
                current_value_node.value = deep_merge_mappings(current_value_node.value, value_node.value)
            else:
                merged_dict[key_node.value] = value_node
        else:
            merged_dict[key_node.value] = value_node

    result = []
    for key, value in merged_dict.items():
        result.append((key_node.constructor.yamltype_to_object_type(key_node.tag, key), value))

    return result

def deep_merge_nodes(nodes):
    merged_dict = {}
    for key, value in nodes:
        if key.value not in merged_dict:
            merged_dict[key.value] = value
        else:
            if value.kind == ruamel.yaml.nodes.MappingNode:
                merged_value = merged_dict[key.value]
                if merged_value.kind == ruamel.yaml.nodes.MappingNode:
                    merged_dict[key.value] = deep_merge_mappings(merged_value, value)
                else:
                    merged_dict[key.value] = value
            else:
                merged_dict[key.value] = value
    return [(key, value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    def _merge_node(left, right):
        if isinstance(left, MappingNode) and isinstance(right, MappingNode):
            merged_value = left.value.copy()
            for key, right_value in right.value.items():
                if key in merged_value:
                    merged_value[key] = _merge_node(merged_value[key], right_value)
                else:
                    merged_value[key] = right_value
            return left.__class__(left.tag, merged_value)
        else:
            return right

    merged_nodes = []
    for key, value in nodes:
        if any(n[0] == key for n in merged_nodes):
            for i, (n_key, n_value) in enumerate(merged_nodes):
                if n_key == key:
                    merged_nodes[i] = (n_key, _merge_node(n_value, value))
                    break
        else:
            merged_nodes.append((key, value))

    return merged_nodes

def deep_merge_nodes(nodes):
    merged = {}
    for key_node, value_node in nodes:
        if key_node.value not in merged:
            merged[key_node.value] = value_node
        else:
            if isinstance(value_node, MappingNode) and isinstance(merged[key_node.value], MappingNode):
                child_pairs = list(value_node.value) + list(merged[key_node.value].value)
                merged[key_node.value] = MappingNode(tag='tag:yaml.org,2002:map', value=child_pairs)
            else:
                merged[key_node.value] = value_node
    return [(ScalarNode(tag='tag:yaml.org,2002:str', value=key), value) for key, value in merged.items()]

