def parse_arguments(*unparsed_arguments):
    from argparse import ArgumentParser, Namespace
    parsers = {}
    global_parser = ArgumentParser(add_help=False)
    subparsers = global_parser.add_subparsers(dest='subparser_name')

    # Add subparsers here
    # Example:
    # subparser = subparsers.add_parser('example')
    # subparser.add_argument('--example_arg', type=str)

    args = global_parser.parse_args(unparsed_arguments)

    # Process each subparser
    for arg in args._get_kwargs():
        if arg[0] != 'subparser_name' and arg[1] is not None:
            if args.subparser_name in parsers:
                getattr(parsers[args.subparser_name], arg[0]) = arg[1]
            else:
                parsers[args.subparser_name] = Namespace()
                setattr(parsers[args.subparser_name], arg[0], arg[1])

    # Return global arguments if no subparser is specified
    if args.subparser_name is None:
        parsers['global'] = args

    return parsers

