    if isinstance(commands, str):
        commands = [commands]

    final_args = []
    for command in commands:
        final_args.extend([command] + args)

    run_args = final_args

    if not hide_stderr:
        if verbose:
            subprocess.run(run_args, cwd=cwd, env=env, check=True)
        else:
            subprocess.run(run_args, cwd=cwd, env=env, check=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    else:
        if verbose:
            subprocess.run(run_args, cwd=cwd, env=env, check=True)
        else:
            subprocess.run(run_args, cwd=cwd, env=env, check=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)

    return subprocess.run(run_args, cwd=cwd, env=env, capture_output=True, text=True).stdout

