def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    mismatch = []

    if tentative:
        for attr, type in iface.REQUIRED_ATTRIBS:
            if not hasattr(candidate, attr):
                mismatch.append(attr)
        for method, doparam, returns in iface.REQUIRED_METHODS:
            if not callable(getattr(candidate, method, None)):
                mismatch.append(method)
        for attr, type in iface.REQUIRED_SKIPPED_ATTRIBS:
            if hasattr(candidate, attr):
                mismatch.append(attr)
        for method, doparam, returns in iface.REQUIRED_SKIPPED_METHODS:
            if callable(getattr(candidate, method, None)):
                mismatch.append(method)
    else:
        for attr, type in iface.REQUIRED_ATTRIBS:
            if not isinstance(getattr(candidate, attr, None), type):
                mismatch.append(attr)
        for method, doparam, returns in iface.REQUIRED_METHODS:
            method = getattr(candidate, method, None)
            if not callable(method):
                mismatch.append(method)
            elif doparam:
                argcount = len(inspect.getargspec(method).args) - 1  # subtract 1 for self
                if argcount != 1:
                    mismatch.append(method)
            elif returns != method():
                mismatch.append(method)
        for attr, type in iface.REQUIRED_SKIPPED_ATTRIBS:
            if isinstance(getattr(candidate, attr, None), type):
                mismatch.append(attr)
        for method, doparam, returns in iface.REQUIRED_SKIPPED_METHODS:
            method = getattr(candidate, method, None)
            if callable(method):
                if doparam:
                    argcount = len(inspect.getargspec(method).args) - 1  # subtract 1 for self
                    if argcount != 1:
                        mismatch.append(method)
                elif returns != method():
                    mismatch.append(method)

    if mismatch:
        raise VerificationError(f"Class {candidate.__class__.__name__} does not match interface {iface.__name__}: {', '.join(mismatch)}")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    # Check if the candidate duck-types the interface
    for method_name in iface.__dict__:
        if callable(iface.__dict__[method_name]):
            method = getattr(candidate, method_name, None)
            if method is None or not callable(method):
                if tentative:
                    return False  # Tentative mode: return False but don't raise an error
                else:
                    raise AttributeError(f"Class {candidate.__class__.__name__} does not provide method {method_name}")

    if tentative:
        return True  # Tentative mode: return True indicating the candidate might provide the interface

    # Check if the candidate's class is a subclass of the interface
    if not issubclass(candidate.__class__, iface):
        raise TypeError(f"Class {candidate.__class__.__name__} is not a subclass of {iface.__name__}")

    return True

